# Editar /etc/bind/named.conf.options
options {
    directory "/var/cache/bind";
    recursion yes;  # Permite consultas recursivas de clientes
    allow-query { 192.168.1.0/24; };  # Solo red local

    # Forwarders: si no tenemos la respuesta, preguntamos a estos
    forwarders {
        8.8.8.8;
        8.8.4.4;
    };
};

# Verificar sintaxis
named-checkconf

# Reiniciar
systemctl restart bind9
systemctl enable bind9

# Añadir en /etc/bind/named.conf.local
zone "midominio.local" {
    type master;
    file "/var/cache/bind/db.midominio.local";
};

# Añadir en /etc/bind/named.conf.local
zone "1.168.192.in-addr.arpa" {
    type master;
    file "/var/cache/bind/db.192.168.1";
};
